  external ffi.Pointer<ffi.Uint8> ptr;

  @ffi.UintPtr()
  external int len;

  static ffi.Pointer<ZanshinBuf> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Uint8> ptr,
    required int len,
  }) => $allocator<ZanshinBuf>()
    ..ref.ptr = ptr
    ..ref.len = len;
}
